     default_qty_type=strategy.percent_of_equity, default_qty_value=10)
len = input.int(10, "Length", minval=1)
m = ta.mom(close, len)
if ta.crossover(m, 0)
    strategy.entry("Long", strategy.long)
if ta.crossunder(m, 0)
    strategy.close("Long")
